    createInvitation: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                /**
                 * @example {
                 *       "email": "new.organiser@talanta.test",
                 *       "role": "ORGANISER"
                 *     }
                 */
                "application/json": components["schemas"]["CreateInvitation"];
            };
        };
        responses: {
            /** @description The invitation, with its `invite_url`. */
            201: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "id": 31,
                     *       "email": "new.organiser@talanta.test",
                     *       "role": "ORGANISER",
                     *       "status": "PENDING",
                     *       "invited_by": {
                     *         "id": 2,
                     *         "name": "Site Admin",
                     *         "email": "admin@talanta.test"
                     *       },
                     *       "expires_at": "2026-10-18T09:00:00Z",
                     *       "created_at": "2026-10-11T09:00:00Z",
                     *       "accepted_at": null,
                     *       "invite_url": "https://talanta.vendorsoko.com/invite/4f9c0d6b1e7a43c2b8d5a1f0e3c7b9d24f9c0d6b1e7a43c2b8d5a1f0e3c7b9d2"
                     *     }
                     */
                    "application/json": components["schemas"]["Invitation"];
                };
            };
            400: components["responses"]["ValidationFailed"];
            401: components["responses"]["Unauthorized"];
            403: components["responses"]["Forbidden"];
            /**
             * @description - `EMAIL_ALREADY_REGISTERED` - a user with this email exists.
             *     - `INVITATION_ALREADY_PENDING` - an unexpired invitation for this email exists; resend or revoke it.
             */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            500: components["responses"]["Internal"];
        };
    };
